def sequential_search(arr, element):
    """
    This function takes in an array and an element, and returns a tuple.
    The tuple contains a boolean indicating whether the element is in the array
    and the index of the element (or -1 if the element is not found).
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)

# Example test
assert sequential_search([11, 23, 58, 31, 56, 77, 43, 12, 65, 19], 31) == (True, 3)
