def max_sub_array_sum_repeated(arr, n, k):
    # Helper function to find the maximum sum of a contiguous subarray (Kadane's algorithm)
    def kadane(nums):
        max_sum = float('-inf')
        current_sum = 0
        for num in nums:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)
        return max_sum

    # Edge case: if k == 1, just apply Kadane's algorithm on the single array
    if k == 1:
        return kadane(arr)

    # Compute Kadane's result for one array
    max_single = kadane(arr)

    # Compute the sum of the entire array
    total_sum = sum(arr)

    # Compute Kadane's result for the array repeated twice
    max_prefix_suffix = kadane(arr * 2)

    if total_sum > 0:
        # If total sum of the array is positive, use the formula:
        # max_single + (k-2)*total_sum + max_prefix_suffix
        return max(max_single, max_prefix_suffix + (k - 2) * total_sum)
    else:
        # If total sum of the array is non-positive, the repetition won't add value
        return max(max_single, max_prefix_suffix)

# Example usage and test
assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
```

