def count_Substrings(s):
    def digit_sum(sub):
        return sum(int(char) for char in sub)

    n = len(s)
    count = 0

    # Check all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            if digit_sum(substring) == len(substring):
                count += 1

    return count

# Example usage
assert count_Substrings('112112') == 6
```

