def tuple_to_dict(input_tuple):
    """
    Converts a tuple into a dictionary using adjacent elements as key-value pairs.

    :param input_tuple: Tuple containing elements to be converted into a dictionary
    :return: Dictionary with adjacent elements as key-value pairs
    """
    if len(input_tuple) % 2 != 0:
        raise ValueError("Input tuple must have an even number of elements.")

    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple), 2)}

# Tests
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
assert tuple_to_dict((2, 4, 6, 8)) == {2: 4, 6: 8}
assert tuple_to_dict(()) == {}
assert tuple_to_dict((10, 20)) == {10: 20}
```

