def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merge three dictionaries into a single dictionary.
    If there are duplicate keys, the value from the last dictionary
    in the order will be used.

    Parameters:
        dict1 (dict): First dictionary.
        dict2 (dict): Second dictionary.
        dict3 (dict): Third dictionary.

    Returns:
        dict: Merged dictionary sorted by keys.
    """
    merged_dict = {**dict1, **dict2, **dict3}
    return dict(sorted(merged_dict.items()))

# Example Usage
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'G': 'Green', 'O': 'Orange', 'P': 'Pink', 'R': 'Red', 'W': 'White'}

assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"L": "lavender", "B": "Blue"}
) == {'B': 'Blue', 'G': 'Green', 'L': 'lavender', 'P': 'Pink', 'R': 'Red', 'W': 'White'}
